import{_ as t,o,c as s,a2 as a}from"./chunks/framework.BXzK3EA4.js";const u=JSON.parse('{"title":"Getting started","description":"","frontmatter":{},"headers":[],"relativePath":"development/getting-started.md","filePath":"development/getting-started.md","lastUpdated":1788529216000}'),d={name:"development/getting-started.md"};function n(r,e,i,c,p,l){return o(),s("div",null,[...e[0]||(e[0]=[a(`<h1 id="getting-started" tabindex="-1">Getting started <a class="header-anchor" href="#getting-started" aria-label="Permalink to &quot;Getting started&quot;">​</a></h1><p>The repository targets .NET 10 and KubeOps 13.2.0. Install the .NET 10 SDK, Node.js 22, Docker Desktop or Rancher Desktop with a working container engine, and Helm before starting.</p><p>Run the KubeOps operator/API with <code>dotnet run --project src/AegisScan.Operator</code> from the repository root. It listens on <code>:8080</code> by default; set <code>ASPNETCORE_URLS</code> to change the address.</p><p>Run the UI with:</p><div class="language-powershell vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">powershell</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">cd web</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npm install</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">npm run dev</span></span></code></pre></div><p>The UI uses the API by default and the Vite server proxies <code>/api</code> to <code>http://127.0.0.1:8080</code>. Set <code>VITE_API_BASE_URL</code> only when the API is hosted at another base URL. Fixture mode is reserved for automated UI tests and must be explicitly enabled with <code>VITE_FIXTURE_MODE=true</code>.</p><p>For a live local stack with frontend hot reload, start the infrastructure and API with <code>docker compose up -d --build</code>, then run the Vite override with <code>docker compose -f docker-compose.yml -f docker-compose.dev.yml up web</code>. Open <code>http://localhost:4173</code>; edits under <code>web/src</code> reload immediately and API requests still go through the real .NET operator/API, PostgreSQL, and k3s stack.</p><p>Validation commands are <code>dotnet test tests/AegisScan.Operator.Tests</code>, <code>npm run test</code>, <code>npm run build</code> from <code>web</code>, and <code>npm run build</code> from <code>docs</code>.</p>`,8)])])}const m=t(d,[["render",n]]);export{u as __pageData,m as default};
